def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    fill={(4,4):8,(6,6):4,(8,8):3}
    for r1 in range(h):
      for r2 in range(r1+2,h):
       for c1 in range(w):
        for c2 in range(c1+2,w):
         if (r2-r1,c2-c1) in fill and all(g[r1][c]==2 and g[r2][c]==2 for c in range(c1,c2+1)) and all(g[r][c1]==2 and g[r][c2]==2 for r in range(r1,r2+1)):
          color=fill[(r2-r1,c2-c1)]
          for r in range(r1+1,r2):
           for c in range(c1+1,c2):
            if g[r][c]==0:g[r][c]=color
    return g
